import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header';
import { HeroPage } from './components/HeroPage';
import { MenuPage } from './components/MenuPage';
import { CartDrawer } from './components/CartDrawer';
import { Footer } from './components/Footer';
import { LoginModal } from './modals/LoginModal';
import { RegisterModal } from './modals/RegisterModal';
import { ReserveModal } from './modals/ReserveModal';
import { Icons } from './components/ui/Icons';  // <-- ДОБАВЬТЕ ЭТУ СТРОКУ
import { useToast } from './hooks/useToast';
import './styles/global.css';

export default function App() {
    const [page, setPage] = useState("home");
    const [modal, setModal] = useState(null);
    const [cart, setCart] = useState([]);
    const [cartOpen, setCartOpen] = useState(false);
    const [scrolled, setScrolled] = useState(false);
    const toast = useToast();

    useEffect(() => {
        const handleScroll = () => setScrolled(window.scrollY > 20);
        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    const addToCart = useCallback(dish => {
        setCart(c => {
            const ex = c.find(i => i.id === dish.id);
            return ex
                ? c.map(i => i.id === dish.id ? { ...i, qty: i.qty + 1 } : i)
                : [...c, { ...dish, qty: 1 }];
        });
    }, []);

    const setQty = (id, delta) => setCart(c =>
        c.map(i => i.id === id ? { ...i, qty: Math.max(1, i.qty + delta) } : i)
    );

    const removeItem = id => setCart(c => c.filter(i => i.id !== id));
    const cartCount = cart.reduce((s, i) => s + i.qty, 0);

    return (
        <>
            <Header
                scrolled={scrolled}
                page={page}
                setPage={setPage}
                setModal={setModal}
                setCartOpen={setCartOpen}
                cartCount={cartCount}
            />

            {page === "home" && <HeroPage onAddToCart={addToCart} toast={toast} setPage={setPage} />}
            {page === "menu" && <MenuPage onAddToCart={addToCart} toast={toast} />}

            <Footer
                setModal={setModal}
                setPage={setPage}
                setCartOpen={setCartOpen}
                cartCount={cartCount}
                toast={toast}
            />

            {modal === "login" && (
                <LoginModal
                    onClose={() => setModal(null)}
                    onRegister={() => setModal("register")}
                    toast={toast}
                />
            )}
            {modal === "register" && (
                <RegisterModal
                    onClose={() => setModal(null)}
                    onLogin={() => setModal("login")}
                    toast={toast}
                />
            )}
            {modal === "reserve" && (
                <ReserveModal
                    onClose={() => setModal(null)}
                    toast={toast}
                />
            )}

            {cartOpen && (
                <CartDrawer
                    cart={cart}
                    onClose={() => setCartOpen(false)}
                    onQty={setQty}
                    onRemove={removeItem}
                    toast={toast}
                />
            )}

            <div className="toast-wrap">
                {toast.list.map(t => (
                    <div key={t.id} className={`toast ${t.type}`}>
                        {t.type === "ok" ? <Icons.Check /> : <Icons.XIcon />}
                        {t.msg}
                    </div>
                ))}
            </div>
        </>
    );
}
